/** Sidens slug uden skraastreg — ruterne bor under /uk/<slug>. */
// ⚠️ INTERNE UK-LINKS SKAL BAERE /uk-PRAEFIKSET.
// Proxy'en rewriter kun paa en GB-vaert: paa getbirdly.co.uk bliver /terms til
// /uk/terms af sig selv. Men previewet koerer paa www.birdly.dk/uk, og dér
// sker der ingen rewrite - saa et link til "/terms" ramte 404. Maalt
// 10-09-2026: alle ti juraside var doede paa previewet, mens de virkede paa
// GB-vaerten. Med praefikset virker de BEGGE steder, for proxy'en lader en
// sti der allerede starter med /uk passere uroert.
//
// ⚠️ PRISEN ER KOSMETISK: paa det britiske domaene staar der /uk/terms i
// adresselinjen frem for /terms. Canonical peger fortsat paa den korte form.
// Naar DNS er sat op og previewet ikke laengere er den danske vaert, kan de
// forkortes - det er den her konstant, ikke tyve kaldesteder.
export const UK_BASE = "/uk";

/** En UK-rute med det praefiks der virker paa begge vaerter. */
export function ukSti(rute) {
  return UK_BASE + rute;
}

export const UK_JURA_SLUGS = UK_JURA.map((s) => s.rute.replace(/^\//, ""));

/**
 * Dokumentets EGEN overskrift — den foerste `# ` i markdown'en.
 *
 * ⚠️ IKKE `titel`. `titel` er pakkens sektionsnavn ("PRIVACY POLICY", med
 * versaler), som er en overskrift i KILDEDOKUMENTET, ikke paa siden. Brugt som
 * <title> blev fanen til "PRIVACY POLICY | Birdly". Dokumentets egen h1 siger
 * "Privacy Policy", og det er den kunden ser oeverst paa siden.
 */
export function juraOverskrift(side) {
  const m = side.md.match(/^# (.+)$/m);
  return m ? m[1].trim() : side.titel;
}

/**
 * Ét afsnit ud af en juraside, som markdown.
 *
 * ⚠️ DEN FINDES SÅ "Report a problem" IKKE BLIVER EN ANDEN UDGAVE AF SANDHEDEN.
 * Pakkens note 11 beder om en synlig rute, men giver ingen tekst til den.
 * Private Job Terms §12 ("Problems with a business") ER teksten — den siger
 * allerede hvad man gør, og hvor man skriver hen. Skrev jeg en ny side op ved
 * siden af, ville vi have to formuleringer af den samme rettighed, og de kunne
 * skride fra hinanden uden at nogen så det.
 *
 * Afsnittet hentes derfor HERFRA, så det er dækket af verify-uk-jura.mjs som
 * alt andet jura.
 */
export function juraAfsnit(rute, overskrift) {
  const side = UK_JURA.find((s) => s.rute === rute);
  if (!side) return null;
  const start = side.md.indexOf(overskrift);
  if (start < 0) return null;
  const efter = side.md.indexOf("\n## ", start + overskrift.length);
  return side.md.slice(start, efter < 0 ? undefined : efter).trim();
}

// ══ HUB'ENS KORT ══
//
// ⚠️ RAEKKEFOELGEN ER PAKKENS EGEN. Dokumenterne staar i "## Documents" i
// den raekkefoelge pakken har valgt, og hub'en viser dem i samme. Aendrer
// pakken raekkefoelgen, flytter kortene sig med - de er ikke skrevet af her.
//
// ⚠️ RUTERNE PARRES EKSPLICIT, IKKE VED AT GAETTE PAA TITLEN.
// "Terms & Conditions" kunne matche baade /terms-and-conditions og
// /terms-of-use ved en loes sammenligning. Listen her siger det praecist, og
// scripts/verify-uk-jura.mjs faelder beviset hvis et dokument mangler et kort
// eller et kort peger paa en rute der ikke findes.
const HUB_ORDEN = [
  "/terms-and-conditions",
  "/subscription-terms",
  "/terms-of-use",
  "/private-job-terms",
  "/privacy-policy",
  "/cookie-policy",
  "/security",
  "/sub-processors",
  "/data-processing-agreement",
];

/**
 * Hub-siden som strukturerede kort — titel, beskrivelse og knap-tekst,
 * alt sammen klippet ud af pakkens egen "## Documents"-sektion.
 */
export function hubKort() {
  const hub = UK_JURA.find((s) => s.rute === "/terms");
  if (!hub) return [];
  const afsnit = hub.md.split(/^### /m).slice(1);
  return afsnit.map((blok, i) => {
    const linjer = blok.split("\n");
    const titel = linjer[0].trim();
    const krop = linjer.slice(1).join("\n").trim();
    // Sidste fede linje er knappens tekst ("**Read Terms & Conditions →**").
    const knapMatch = krop.match(/\*\*(.+?)\*\*/);
    // ⚠️ KUN TEKSTEN FØR KNAPPEN. Første udgave fjernede bare den fede
    // knap-linje og beholdt resten — og resten er ikke tom på det SIDSTE kort:
    // pakkens "## Documents" slutter med Birdly.dk's postadresse og kontakt,
    // så DPA-kortet stod med "…on behalf of a business customer. Birdly.dk CVR
    // no. 35764283 c/o Jonas Bonde Nielsen Fjordvej 4 4300 Holbæk Denmark
    // Contact: …" som sin beskrivelse. Set på et skærmbillede 10-09-2026.
    // Beskrivelsen er dét der står mellem overskriften og knappen — intet andet.
    const beskrivelse = krop.split("**")[0].trim();
    return {
      rute: HUB_ORDEN[i] || null,
      titel,
      beskrivelse,
      knap: knapMatch ? knapMatch[1].replace(/\s*→\s*$/, "").trim() : null,
    };
  });
}

/** Hub'ens indledning — alt foer "## Documents". */
export function hubIndledning() {
  const hub = UK_JURA.find((s) => s.rute === "/terms");
  if (!hub) return { overskrift: "", brod: [] };
  const foer = hub.md.slice(0, hub.md.indexOf("## Documents"));
  const linjer = foer.split("\n").map((l) => l.trim()).filter(Boolean);
  return {
    overskrift: (linjer[0] || "").replace(/^#\s*/, ""),
    brod: linjer.slice(1),
  };
}

export function juraSide(slug) {
  return UK_JURA.find((s) => s.rute === "/" + slug) || null;
}
